PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user',upload_approved INTEGER NOT NULL DEFAULT 0,pack_maker INTEGER NOT NULL DEFAULT 0,best_approved INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT(datetime('now')),last_seen TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS posts(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,body TEXT NOT NULL,image_url TEXT DEFAULT '',category TEXT DEFAULT 'مود',author_id INTEGER,download_url TEXT DEFAULT '',image_data TEXT DEFAULT '',view_count INTEGER NOT NULL DEFAULT 0,download_count INTEGER NOT NULL DEFAULT 0,featured INTEGER NOT NULL DEFAULT 0,staff_pick INTEGER NOT NULL DEFAULT 0,tags TEXT DEFAULT '',created_at TEXT NOT NULL DEFAULT(datetime('now')),FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,username TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS comments(id INTEGER PRIMARY KEY AUTOINCREMENT,post_id INTEGER NOT NULL,user_id INTEGER,username TEXT NOT NULL,body TEXT NOT NULL,parent_id INTEGER,created_at TEXT NOT NULL DEFAULT(datetime('now')),FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS favorites(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,post_id INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(user_id,post_id));
CREATE TABLE IF NOT EXISTS ratings(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,post_id INTEGER NOT NULL,rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),created_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(user_id,post_id));
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,read_at TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS email_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,admin_id INTEGER,recipient_count INTEGER NOT NULL DEFAULT 0,subject TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS site_stats(id INTEGER PRIMARY KEY CHECK(id=1),visits INTEGER NOT NULL DEFAULT 0,downloads INTEGER NOT NULL DEFAULT 0);INSERT OR IGNORE INTO site_stats(id) VALUES(1);
